enum { IDLE, WAIT } st = IDLE;
uint32_t t0;
void step(uint32_t now, bool btn) {
  if (st == IDLE && btn) {
    st = WAIT;
    t0 = now;   // start the 2 s timer here
    led_on();
  } else if (st == WAIT && now - t0 >= 2000) {
    led_off();
    st = IDLE;
  }
}

